/**
 * lib/db.js — a callback-style database API.
 *
 * Underneath this is node:sqlite, which is SYNCHRONOUS: a local SQLite query
 * is microseconds of CPU, not a wait, so there is genuinely nothing to await.
 * This wrapper adds a small delay and a callback so that the API behaves like
 * the database drivers you will actually meet — where every query is a round
 * trip over the network and therefore real I/O.
 *
 * You do not edit this file during the session. It is the only thing standing
 * between you and a `npm install` that needs a compiler.
 *
 *   open(filename, callback)          -> callback(err, db)
 *   db.run(sql, params, callback)     -> callback(err, { changes, lastInsertRowid })
 *   db.get(sql, params, callback)     -> callback(err, row)
 *   db.all(sql, params, callback)     -> callback(err, rows)
 *   db.exec(sql, callback)            -> callback(err)
 *   db.close(callback)                -> callback(err)
 */

const { DatabaseSync } = require('node:sqlite');

// How long we pretend the network takes. Raise it to make the difference
// between sequential and concurrent code more obvious on the projector.
const LATENCY_MS = 15;

const later = (fn) => setTimeout(fn, LATENCY_MS);

function open(filename, callback) {
  later(() => {
    let inner;
    try {
      inner = new DatabaseSync(filename);
    } catch (err) {
      callback(err);
      return;
    }
    callback(null, wrap(inner));
  });
}

function wrap(inner) {
  const guard = (work, callback) => {
    later(() => {
      let result;
      try {
        result = work();
      } catch (err) {
        callback(err);
        return;
      }
      callback(null, result);
    });
  };

  return {
    exec(sql, callback) {
      guard(() => inner.exec(sql), (err) => callback(err));
    },

    run(sql, params, callback) {
      guard(() => {
        const info = inner.prepare(sql).run(...params);
        return { changes: Number(info.changes), lastInsertRowid: Number(info.lastInsertRowid) };
      }, callback);
    },

    get(sql, params, callback) {
      guard(() => inner.prepare(sql).get(...params) ?? null, callback);
    },

    all(sql, params, callback) {
      guard(() => inner.prepare(sql).all(...params), callback);
    },

    close(callback) {
      guard(() => inner.close(), (err) => callback(err));
    },
  };
}

module.exports = { open, LATENCY_MS };
